package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"strings"
	"time"
)

var encryptionKey = []byte("orchestrator-key-32bytes-long!!!")

type ContainerSession struct {
	UserID    string `json:"uid"`
	ClusterID string `json:"cid"`
	Role      string `json:"role"`
	Expiry    int64  `json:"exp"`
}

func pkcs7Pad(data []byte, blockSize int) []byte {
	padLen := blockSize - len(data)%blockSize
	padding := make([]byte, padLen)
	for i := range padding {
		padding[i] = byte(padLen)
	}
	return append(data, padding...)
}

func pkcs7Unpad(data []byte) ([]byte, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty data")
	}
	padLen := int(data[len(data)-1])
	if padLen == 0 || padLen > aes.BlockSize {
		return nil, fmt.Errorf("invalid padding length")
	}
	if padLen > len(data) {
		return nil, fmt.Errorf("padding exceeds data length")
	}
	for i := len(data) - padLen; i < len(data); i++ {
		if data[i] != byte(padLen) {
			return nil, fmt.Errorf("invalid padding byte")
		}
	}
	return data[:len(data)-padLen], nil
}

func encryptSession(session *ContainerSession) (string, error) {
	plaintext, err := json.Marshal(session)
	if err != nil {
		return "", err
	}
	padded := pkcs7Pad(plaintext, aes.BlockSize)
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return "", err
	}
	ciphertext := make([]byte, aes.BlockSize+len(padded))
	iv := ciphertext[:aes.BlockSize]
	if _, err := io.ReadFull(rand.Reader, iv); err != nil {
		return "", err
	}
	mode := cipher.NewCBCEncrypter(block, iv)
	mode.CryptBlocks(ciphertext[aes.BlockSize:], padded)
	return base64.URLEncoding.EncodeToString(ciphertext), nil
}

func decryptSession(token string) (*ContainerSession, error) {
	ciphertext, err := base64.URLEncoding.DecodeString(token)
	if err != nil {
		return nil, fmt.Errorf("decode error")
	}
	if len(ciphertext) < aes.BlockSize*2 {
		return nil, fmt.Errorf("ciphertext too short")
	}
	if len(ciphertext)%aes.BlockSize != 0 {
		return nil, fmt.Errorf("invalid ciphertext length")
	}
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}
	iv := ciphertext[:aes.BlockSize]
	encrypted := ciphertext[aes.BlockSize:]
	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(encrypted, encrypted)
	plaintext, err := pkcs7Unpad(encrypted)
	if err != nil {
		return nil, fmt.Errorf("padding error")
	}
	var session ContainerSession
	if err := json.Unmarshal(plaintext, &session); err != nil {
		return nil, fmt.Errorf("session parse error")
	}
	return &session, nil
}

type ProxyHandler struct {
	requestLog map[string][]time.Time
}

func (h *ProxyHandler) validateAndRoute(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("X-Container-Auth")
	if authHeader == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	parts := strings.SplitN(authHeader, " ", 2)
	if len(parts) != 2 || parts[0] != "Bearer" {
		http.Error(w, "malformed auth", http.StatusBadRequest)
		return
	}
	session, err := decryptSession(parts[1])
	if err != nil {
		errMsg := err.Error()
		if strings.Contains(errMsg, "padding") {
			w.WriteHeader(http.StatusBadRequest)
			w.Write([]byte(`{"error":"token_integrity_failure","code":"E4001"}`))
		} else if strings.Contains(errMsg, "decode") {
			w.WriteHeader(http.StatusBadRequest)
			w.Write([]byte(`{"error":"token_format_invalid","code":"E4002"}`))
		} else {
			w.WriteHeader(http.StatusUnauthorized)
			w.Write([]byte(`{"error":"token_expired_or_invalid","code":"E4003"}`))
		}
		return
	}
	if session.Expiry < time.Now().Unix() {
		http.Error(w, `{"error":"session_expired","code":"E4004"}`, http.StatusUnauthorized)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":  "routed",
		"cluster": session.ClusterID,
		"user":    session.UserID,
		"role":    session.Role,
	})
}

func (h *ProxyHandler) issueToken(w http.ResponseWriter, r *http.Request) {
	var req struct {
		UserID    string `json:"user_id"`
		ClusterID string `json:"cluster_id"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	session := &ContainerSession{
		UserID:    req.UserID,
		ClusterID: req.ClusterID,
		Role:      "viewer",
		Expiry:    time.Now().Add(24 * time.Hour).Unix(),
	}
	token, err := encryptSession(session)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"token": token})
}

func main() {
	handler := &ProxyHandler{
		requestLog: make(map[string][]time.Time),
	}
	http.HandleFunc("/api/v1/route", handler.validateAndRoute)
	http.HandleFunc("/api/v1/token", handler.issueToken)
	log.Println("Container orchestration proxy starting on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
